"""Removes users and organizations created by `make smoke`, `make e2e` and the audit scripts.

Only rows whose email matches the throwaway patterns below are touched, and only when
KMR_APP_ENV is "local". Run with `--dry-run` to see counts without deleting anything.
"""

import shutil
import sys

import psycopg

from app.config import get_settings

# Emails generated by the scripts in frontend/scripts (e2e, smoke, a11y audit, showcase) and
# scripts/load-check.py.
_PATTERNS = (
    "e2e-owner-%@example.com",
    "e2e-mate-%@example.com",
    "smoke-%@example.com",
    "a11y-%@example.com",
    "showcase-%@example.com",
    "load-%@example.com",
)


def main() -> int:
    settings = get_settings()
    if settings.app_env != "local":
        print("Refusing to run: KMR_APP_ENV is not 'local'.", file=sys.stderr)
        return 1
    if settings.migration_database_url is None:
        print("Set KMR_MIGRATION_DATABASE_URL in .env", file=sys.stderr)
        return 1
    dry_run = "--dry-run" in sys.argv
    url = settings.migration_database_url.get_secret_value().replace(
        "postgresql+psycopg://", "postgresql://", 1
    )
    where = " OR ".join(["email LIKE %s"] * len(_PATTERNS))
    with psycopg.connect(url) as conn:
        users = [
            row[0]
            for row in conn.execute(f"SELECT id FROM users WHERE {where}", _PATTERNS).fetchall()  # noqa: S608
        ]
        if not users:
            print("No test data found.")
            return 0
        orgs = [
            row[0]
            for row in conn.execute(
                "SELECT id FROM organizations WHERE created_by = ANY(%s)", (users,)
            ).fetchall()
        ]
        audit = conn.execute(
            "SELECT count(*) FROM audit_events WHERE org_id = ANY(%s) OR actor_user_id = ANY(%s)",
            (orgs, users),
        ).fetchone()
        events = audit[0] if audit else 0
        print(f"users: {len(users)}, organizations: {len(orgs)}, audit events: {events}")
        if dry_run:
            conn.rollback()
            print("Dry run: nothing deleted.")
            return 0
        # Order matters: audit rows reference organizations, organizations reference users.
        conn.execute(
            "DELETE FROM audit_events WHERE org_id = ANY(%s) OR actor_user_id = ANY(%s)",
            (orgs, users),
        )
        conn.execute("DELETE FROM organizations WHERE id = ANY(%s)", (orgs,))
        conn.execute("DELETE FROM users WHERE id = ANY(%s)", (users,))
        conn.commit()
    # Screenshots live on disk, not in the database: remove those organizations' folders too.
    removed = 0
    for org_id in orgs:
        folder = settings.evidence_dir / str(org_id)
        if folder.is_dir():
            shutil.rmtree(folder)
            removed += 1
    print(f"Deleted. Removed {removed} evidence folder(s).")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
